import Image from "next/image";

import { cn } from "@/lib/utils";

/**
 * The MP mark on transparency. Generated by `bun run brand:assets`; it keeps its
 * true colours, so it reads on the light canvas and on the dark footer alike.
 */
export function BrandMark({ className, preload }: { className?: string; preload?: boolean }) {
  return (
    <Image
      src="/brand/logo-mark.png"
      alt=""
      width={512}
      height={512}
      sizes="80px"
      preload={preload}
      className={cn("size-8 shrink-0 object-contain", className)}
    />
  );
}

/** Mark + EMPEESS wordmark. Size the wordmark with `className` (font-size); the mark follows it. */
export function BrandLogo({ className }: { className?: string }) {
  return (
    <span className={cn("inline-flex items-center gap-[0.3em] font-logo font-semibold uppercase tracking-tight", className)}>
      <BrandMark className="size-[1.35em]" />
      <span>Empeess</span>
    </span>
  );
}
